const trimManagedSecretUses = `-- name: TrimManagedSecretUses :exec
DELETE FROM managed_secret_uses
WHERE managed_secret_uses.secret_id = ?1
  AND managed_secret_uses.id NOT IN (
      SELECT recent.id FROM managed_secret_uses recent
      WHERE recent.secret_id = ?1
      ORDER BY recent.used_at DESC, recent.rowid DESC
      LIMIT ?2
  )
`

type TrimManagedSecretUsesParams struct {
	SecretID string `json:"secret_id"`
	Keep     int64  `json:"keep"`
}

// Keeps the newest uses within the rolling limit.
func (q *Queries) TrimManagedSecretUses(ctx context.Context, arg TrimManagedSecretUsesParams) error {
	_, err := q.db.ExecContext(ctx, trimManagedSecretUses, arg.SecretID, arg.Keep)
	return err
}

const updateManagedSecret = `-- name: UpdateManagedSecret :execrows
UPDATE managed_secrets
SET name = ?1,
    purpose = ?2,
    scope = ?3,
    chat_session_id = ?4,
    agent_use_ends_at = ?5
WHERE id = ?6 AND project_id = ?7 AND revoked_at IS NULL
`

type UpdateManagedSecretParams struct {
	Name           string         `json:"name"`
	Purpose        string         `json:"purpose"`
	Scope          string         `json:"scope"`
	ChatSessionID  sql.NullString `json:"chat_session_id"`
	AgentUseEndsAt sql.NullString `json:"agent_use_ends_at"`
	ID             string         `json:"id"`
	ProjectID      string         `json:"project_id"`
}

// Writes merged metadata unless the capability is revoked.
func (q *Queries) UpdateManagedSecret(ctx context.Context, arg UpdateManagedSecretParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateManagedSecret,
		arg.Name,
		arg.Purpose,
		arg.Scope,
		arg.ChatSessionID,
		arg.AgentUseEndsAt,
		arg.ID,
		arg.ProjectID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

